import math

def fspl_db(f_mhz, d_km):
    # Rec. ITU-R P.525-5, eq. (6)
    return 32.4 + 20 * math.log10(f_mhz) + 20 * math.log10(d_km)

def q_rad_w(area_m2, eps, t_hot_k, t_sink_k, sigma=5.6697e-8):
    # ECSS-E-HB-31-01 Part 9A: sigma and the coating emittance
    return eps * sigma * area_m2 * (t_hot_k ** 4 - t_sink_k ** 4)

def per_km2(n_units, unit_bps, area_km2):
    return n_units * unit_bps / area_km2

print("FSPL  1980 MHz / 1500 km : %.1f dB" % fspl_db(1980, 1500))
print("FSPL  1980 MHz / 35786 km: %.1f dB" % fspl_db(1980, 35786))
print("rad   6.88 m2, eps 0.9, 293 K vs 253 K : %.0f W" % q_rad_w(6.88, 0.9, 293, 253))
print("dens  8 beams x 2 Mbit/s over 5000 km2 : %.2g bit/s/km2" % per_km2(8, 2e6, 5e3))
